/* contain floats and stop margin collapse, with no side effects */
.container { display: flow-root; }

/* the reset that makes 200px mean 200px */
*, *::before, *::after { box-sizing: border-box; }

.bar {
  display: flex;
  flex-flow: row wrap;      /* direction + wrap */
  justify-content: space-between;  /* along the main axis */
  align-items: center;             /* across the cross axis */
  align-content: flex-start;       /* only matters once wrapped */
  gap: 1rem;
}

/* equal columns whatever the content */
.col { flex: 1; }          /* 1 1 0%  */

/* content-sized, sharing only the leftover */
.col { flex: auto; }       /* 1 1 auto */

/* the two classic fixes */
.icon  { flex-shrink: 0; }   /* stop the avatar being squashed */
.label { min-width: 0; }     /* let long text truncate instead of overflow */

nav { display: flex; gap: 1rem; }
nav .logout { margin-left: auto; }   /* pushed to the far end */

.card { display: flex; }
.card .badge { align-self: flex-start; }  /* opt out of stretch */

.gallery {
  display: grid;
  gap: 1rem;
  grid-template-columns: repeat(auto-fit, minmax(min(100%, 18rem), 1fr));
}
.safe { grid-template-columns: minmax(0, 1fr) minmax(0, 2fr); } /* can shrink */

.page {
  display: grid;
  grid-template-columns: 200px minmax(0, 1fr) 200px;
  grid-template-areas:
    "head head head"
    "nav  main aside"
    "foot foot foot";
  grid-auto-rows: minmax(4rem, auto);
}
.head { grid-area: head; }

.frame { display: grid; place-items: center; min-height: 100dvh; }

.board {
  display: grid;
  grid-template-columns: repeat(3, 100px);
  justify-content: center;   /* the grid itself, horizontally */
  align-content: center;     /* the grid itself, vertically   */
  justify-items: stretch;    /* each item inside its cell     */
}

.video { aspect-ratio: 16 / 9; width: 100%; }

/* the historical version, and the reason it works */
.legacy { position: relative; padding-top: 56.25%; }   /* % of WIDTH */
.legacy > iframe { position: absolute; inset: 0; width: 100%; height: 100%; }

.page { margin-inline: auto; max-inline-size: 65ch; }  /* direction-agnostic */

.sidebar, .main { container-type: inline-size; }

.card { display: grid; gap: 1rem; }
@container (width >= 30rem) {
