class PaneBoundary extends React.Component {
  state = { error: null };
  static getDerivedStateFromError(error) { return { error }; }
  componentDidCatch(error, info) { log(error, info.componentStack); }
  render() {
    return this.state.error
      ? <Fallback error={this.state.error} onRetry={() => this.setState({ error: null })} />
      : this.props.children;
  }
}

function Newsletter() {
  const [state, formAction, isPending] = useActionState(
    async (_prev, formData) => subscribe(formData.get('email')),
    { ok: false },
  );
  return (
    <form action={formAction}>
      <input name="email" type="email" required />
      <SubmitButton />           {/* reads pending itself */}
      {state.error && <p role="alert">{state.error}</p>}
    </form>
  );
}

function SubmitButton() {
  const { pending } = useFormStatus();   // no props needed
  return <button disabled={pending}>{pending ? 'Sending…' : 'Subscribe'}</button>;
}

